arguments.command:
cat > tests/CheckoutPricing.UnitTests/GoldDiscountTests.cs <<'E'
using System.Linq;

namespace CheckoutPricing.UnitTests;

public class GoldDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var checkout = typeof(CheckoutPricing.Application.ApplicationMarker).Assembly
            .GetTypes().FirstOrDefault(t => t.Name.Contains("Checkout") || t.Name.Contains("Pricing"));

        Assert.True(checkout is not null,
            "No checkout/pricing capability exists, so a Gold 100.00 subtotal cannot yield 95.00.");
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -15

